(()=>{'use strict';
const $=s=>document.querySelector(s),APP=$('#app'),MOD=$('#modalRoot');
const CONFIG=window.PMP_CONFIG||{},configured=/^https:\/\/[-\w.]+\.supabase\.co$/.test(CONFIG.supabaseUrl||'')&&!!CONFIG.supabaseAnonKey;
const db=configured&&window.supabase?window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,experimental:{passkey:true}}}):null;
const MOTHER='นางสาวกีรติยาพร ศิริภัทราณิชา',FATHER='นายสุธาวริน ศิริภัทราณิชา';
const initial=()=>({settings:{mother:MOTHER,motherNick:'เอมมี่',father:FATHER,fatherNick:'อาร์',dueDate:'',discoveredAt:'',motherAge:'',initialWeight:'',discoveryMethod:'',estimatedFrom:'แพทย์/อัลตราซาวด์',gender:'unknown',birthDate:'',birthTime:'',birthWeight:'',birthLength:'',birthPlace:'',doctorPhone:'',girlThai:'ธริยณวรัญชิดา ศิริภัทราณิชา',girlEn:'DHARIYANAVARANCHIDA SIRIPHATTHARANICHA',girlNickTh:'พิวรีน',girlNickEn:'Purine',boyThai:'ธริยาณฌรัณภัทร ศิริภัทราณิชา',boyEn:'DHARIYANASHARANAPHAT SIRIPHATTHARANICHA',boyNickTh:'อันเซล',boyNickEn:'Ansel',userRoles:{}},appointments:[],symptoms:[],kicks:[],tasks:[],photos:[],babyLogs:[],growth:[],vaccines:[],postpartumLogs:[],memories:[],prenatalVisits:[],reminders:[]});
const sections=['appointments','symptoms','kicks','tasks','photos','babyLogs','growth','vaccines','postpartumLogs','memories','prenatalVisits','reminders'];
const presetTasks=[['hospital','เอกสารฝากครรภ์ / สมุดสีชมพู'],['hospital','เลือกโรงพยาบาลและวางแผนการเดินทาง'],['hospital','จัดกระเป๋าไปโรงพยาบาล'],['hospital','เตรียมเอกสารแจ้งเกิด'],['baby','เสื้อผ้าทารกตามสภาพอากาศ'],['baby','ผ้าอ้อมและอุปกรณ์ทำความสะอาด'],['baby','ผ้าห่อตัว / ผ้าขนหนู'],['baby','คาร์ซีทสำหรับเดินทางกลับบ้าน'],['baby','ที่นอนทารกที่เหมาะสมและปลอดภัย'],['baby','อุปกรณ์อาบน้ำสำหรับเด็ก'],['home','พื้นที่นอนปลอดภัย ไม่มีหมอน/ของนุ่มเกินจำเป็น'],['home','เตรียมมุมเปลี่ยนผ้าอ้อม'],['home','ทำความสะอาดอุปกรณ์จำเป็น'],['parent','วางแผนคนช่วยดูแลหลังคลอด'],['parent','เตรียมเสื้อผ้าคุณแม่หลังคลอด'],['parent','สอบถามแพทย์เรื่องนัดติดตามหลังคลอด'],['parent','วางแผนค่าใช้จ่ายและวันลางาน'],['parent','บันทึกเบอร์โรงพยาบาล/ฉุกเฉิน']];
const catLabels={hospital:'เตรียมคลอด',baby:'ของใช้ลูก',home:'บ้านปลอดภัย',parent:'คุณพ่อคุณแม่',other:'อื่น ๆ'};
const photoTypes={family:'ภาพครอบครัว',bump:'9 Months of Mommy',ultrasound:'อัลตราซาวด์',milestone:'ช่วงเวลาสำคัญ',health:'เอกสารสุขภาพ'};
const state={user:null,family:null,data:initial(),members:[],demo:!configured,tab:'home',role:'mother',modalAction:null,mediaUrls:{},kick:null,unlocked:null,pinTries:0,failedAt:0,lastActivity:Date.now(),pinBusy:false,pendingRole:null,careTab:'overview',galleryTab:'all',booted:false};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=(n)=>`<i data-lucide="${n}"></i>`;
const iconize=()=>window.lucide?.createIcons({attrs:{'stroke-width':1.85}});
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const dateUTC=s=>s?new Date(`${s.slice(0,10)}T12:00:00Z`):null;
const dayDiff=(a,b)=>Math.round((dateUTC(b)-dateUTC(a))/86400000);
const fmtDate=s=>{if(!s)return 'ยังไม่ระบุ';let x=new Date(s.length===10?`${s}T12:00:00`:s);return isNaN(x)?'—':new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric'}).format(x)};
const fmtTime=s=>s?new Intl.DateTimeFormat('th-TH',{hour:'2-digit',minute:'2-digit'}).format(new Date(s)):'—';
const when=s=>s?fmtDate(s)+' · '+fmtTime(s):'—';
const titleDate=()=>new Intl.DateTimeFormat('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());
const oid=()=>crypto.randomUUID();
const daysBaby=()=>state.data.settings.birthDate?Math.max(0,dayDiff(state.data.settings.birthDate,today())):0;
const pregnancy=()=>{let d=state.data.settings.dueDate;if(!d)return null;let gest=280-dayDiff(today(),d);return {days:gest,weeks:Math.max(0,Math.floor(gest/7)),remainder:Math.max(0,gest%7),left:dayDiff(today(),d),pct:Math.min(100,Math.max(0,gest/280*100))}};
const isBorn=()=>!!state.data.settings.birthDate;
// Display names are derived from one shared gender selection; never infer from an image or symptoms.
function babyIdentity(){
  const s=state.data.settings||{}, gender=['female','male'].includes(s.gender)?s.gender:'unknown';
  const female=gender==='female', male=gender==='male', known=female||male;
  const thai=known?String(female?s.girlNickTh||'':s.boyNickTh||'').trim():'';
  const english=known?String(female?s.girlNickEn||'':s.boyNickEn||'').trim():'';
  return {gender,known,thai,english,fullTh:known?String(female?s.girlThai||'':s.boyThai||'').trim():'',fullEn:known?String(female?s.girlEn||'':s.boyEn||'').trim():'',
    displayTh:thai?`น้อง${thai}`:'ลูกน้อย',displayEn:english||'Our baby',sexLabel:female?'ลูกสาว':male?'ลูกชาย':'ยังไม่ทราบเพศ'};
}

const arr=k=>Array.isArray(state.data[k])?state.data[k]:[];
const ordered=(k,dateKey='createdAt')=>[...arr(k)].sort((a,b)=>String(b[dateKey]||'').localeCompare(String(a[dateKey]||'')));
const toast=(msg,bad=false)=>{const root=$('#toastRoot');root.innerHTML=`<div class="toast" style="background:${bad?'#a56e73':'#627f78'}">${esc(msg)}</div>`;setTimeout(()=>{if(root)root.innerHTML=''},3300)};
function mergeLocal(d){let base=initial();return {...base,...d,settings:{...base.settings,...(d?.settings||{})}}}
const inDemo=()=>state.demo;
function demoStart(){state.demo=true;state.user={id:'preview-user',email:'demo@example.invalid'};state.family={id:'demo-family',title:'Our Little Family'};state.data=initial();state.data.tasks=presetTasks.map(([category,title])=>({id:oid(),category,title,done:false,createdAt:new Date().toISOString()}));state.role=rememberedRole()||'mother';state.pendingRole=null;state.unlocked=null;state.tab='home';renderPin()}
async function boot(){if(!db){renderWelcome();return}try{const {data:{user},error}=await db.auth.getUser();if(error||!user){state.user=null;renderWelcome();return}state.user=user;state.demo=false;state.pendingRole=null;const savedRole=localStorage.getItem('pmp-role-'+user.id);if(savedRole==='mother'||savedRole==='father')state.role=savedRole;if(state.unlocked!==user.id){renderPin();return}await loadFamily()}catch(err){console.error(err);toast('เชื่อมต่อระบบไม่สำเร็จ กรุณาลองใหม่',true);renderWelcome()}}
async function loadFamily(){try{await db.rpc('accept_pending_invites');let {data:members,error:me}=await db.from('family_members').select('family_id,role,user_id').eq('user_id',state.user.id).limit(1);if(me)throw me;if(!members?.length){state.family=null;renderOnboarding();return}const fid=members[0].family_id;let {data:family,error}=await db.from('families').select('id,title,data,version').eq('id',fid).single();if(error)throw error;state.family=family;state.data=mergeLocal(family.data);const {data:people}=await db.from('family_members').select('role,user_id,invited_email').eq('family_id',fid);state.members=people||[];if(state.unlocked!==state.user.id){state.role=state.data.settings.userRoles?.[state.user.id]||(members[0].role==='owner'?'mother':'father');}await refreshPhotoUrls();render()}catch(err){console.error(err);toast('โหลดข้อมูลไม่สำเร็จ: '+err.message,true);renderWelcome()}}
async function refresh(){if(!state.demo)await loadFamily();else render()}
function logout(){if(state.demo){state.demo=false;state.user=null;state.family=null;renderWelcome();return}state.unlocked=null;db.auth.signOut().then(()=>{state.user=null;state.family=null;renderWelcome()})}
function renderWelcome(){APP.innerHTML=`<div class="auth-frame pmp-auth-screen"><div class="auth-card pmp-auth-card"><div class="pmp-auth-illustration" aria-hidden="true"><span>♡</span><i>✧</i></div><div class="eyebrow" style="text-align:center">PREGNANT MANAGER PRO · FAMILY ACCESS</div><h1 class="pmp-auth-title">เรื่องราวของเรา<br><em>อยู่ที่นี่เสมอ</em></h1><p class="pmp-auth-sub">ไม่ต้องพิมพ์อีเมลทุกครั้ง — ใช้ Passkey ที่ตั้งไว้ หรือใช้เซสชันเดิมและ PIN 6 หลักของคุณ</p>${db?`<button class="btn pmp-passkey-main" data-act="passkey-signin">${ico('fingerprint')} เข้าสู่ระบบด้วย Passkey</button><p class="pmp-auth-hint">Face ID · ลายนิ้วมือ · PIN ของโทรศัพท์</p>`:''}<details class="pmp-email-details" ${!db?'open':''}><summary>${ico('mail')} ${db?'เข้าใช้งานครั้งแรก / ใช้อีเมลสำรอง':'เข้าสู่ระบบด้วยอีเมล'}</summary><div class="tabs"><button class="tab active" data-auth-tab="login" type="button">เข้าสู่ระบบ</button><button class="tab" data-auth-tab="register" type="button">สมัครบัญชี</button></div><form id="authForm"><div class="field"><label>อีเมล</label><input name="email" type="email" autocomplete="email" required placeholder="name@example.com"></div><div class="field"><label>รหัสผ่าน</label><input name="password" type="password" minlength="8" autocomplete="current-password" required placeholder="อย่างน้อย 8 ตัวอักษร"></div><input type="hidden" name="authMode" value="login"><button type="submit" class="btn" style="width:100%;margin-top:13px">${ico('arrow-right')} เข้าสู่ระบบ</button></form></details><button class="pmp-demo-link" data-act="demo">${ico('sparkles')} ดูตัวอย่างดีไซน์ (ข้อมูลไม่บันทึก)</button><div class="pmp-safety-note">${ico('shield-check')} ข้อมูลสุขภาพเป็นส่วนตัวและใช้ Supabase Auth ตรวจสิทธิ์ทุกครั้ง</div></div></div>`;iconize();$('#authForm').onsubmit=authSubmit}
async function passkeySignIn(){if(!db)return toast('กรุณาตั้งค่า Supabase ก่อน',true);if(typeof db.auth.signInWithPasskey!=='function')return toast('SDK ยังไม่รองรับ Passkey กรุณาอัปเดตเว็บไซต์',true);const btn=document.querySelector('[data-act="passkey-signin"]');if(btn)btn.disabled=true;try{const {data,error}=await db.auth.signInWithPasskey();if(error)throw error;if(!data?.user)throw Error('ไม่ได้รับข้อมูลบัญชีหลังยืนยัน Passkey');state.unlocked=null;applyPendingPinReset(data.user.id);await boot()}catch(err){console.error('Passkey sign-in:',err);toast(passkeyErrorText(err),true)}finally{if(btn?.isConnected)btn.disabled=false}}
async function passkeyRegister(){if(state.demo||!db||!state.user)return toast('ลงชื่อเข้าใช้บัญชีจริงก่อนตั้ง Passkey',true);if(typeof db.auth.registerPasskey!=='function')return toast('SDK ยังไม่รองรับ Passkey',true);const btn=document.querySelector('[data-act="passkey-register"]');if(btn)btn.disabled=true;try{const {error}=await db.auth.registerPasskey();if(error)throw error;toast('เพิ่ม Passkey แล้ว! ต่อไปเข้าใช้งานได้โดยไม่ต้องกรอกอีเมล');}catch(err){console.error('Passkey register:',err);toast(passkeyErrorText(err),true)}finally{if(btn?.isConnected)btn.disabled=false}}
function applyPendingPinReset(uid){const pending=sessionStorage.getItem('pmp-reset-pending');if(!pending)return;try{const item=JSON.parse(pending);if(item.uid===uid&&(item.role==='mother'||item.role==='father')){const k=`pmp-profiles-${uid}`;const profiles=JSON.parse(localStorage.getItem(k)||'{}');delete profiles[item.role];localStorage.setItem(k,JSON.stringify(profiles));localStorage.removeItem(`pmp-pin-rate-${uid}-${item.role}`);localStorage.setItem('pmp-role-'+uid,item.role)}}catch(err){console.warn('PIN reset token invalid',err)}sessionStorage.removeItem('pmp-reset-pending')}
function passkeyErrorText(err){const code=String(err?.code||err?.error_code||'');if(code==='passkey_disabled')return 'กรุณาเปิด Authentication → Passkeys ใน Supabase Dashboard ก่อน';if(code==='webauthn_credential_exists')return 'เครื่องนี้มี Passkey สำหรับบัญชีนี้แล้ว';if(code==='email_not_confirmed')return 'ต้องยืนยันอีเมลก่อนตั้ง Passkey';if(err?.name==='NotAllowedError')return 'ยกเลิกหรือไม่สำเร็จในการยืนยัน Passkey';return String(err?.message||'Passkey ไม่สำเร็จ กรุณาใช้อีเมลสำรอง')}
async function authSubmit(e){e.preventDefault();if(!db)return toast('ต้องตั้งค่า Supabase ก่อนสมัครหรือเข้าสู่ระบบ',true);const fd=new FormData(e.currentTarget),email=String(fd.get('email')).trim(),password=String(fd.get('password')),mode=fd.get('authMode');try{const r=mode==='register'?await db.auth.signUp({email,password}):await db.auth.signInWithPassword({email,password});if(r.error)throw r.error;if(mode==='register'&&!r.data.session){toast('ส่งอีเมลยืนยันแล้ว กรุณายืนยันก่อนเข้าสู่ระบบ');return}state.unlocked=null;applyPendingPinReset(r.data?.user?.id);await boot()}catch(err){toast(err.message||'เข้าสู่ระบบไม่สำเร็จ',true)}}
function renderOnboarding(){APP.innerHTML=`<div class="auth-frame"><div class="auth-card"><div class="brand"><div class="brand-icon">${ico('flower-2')}</div> ตั้งค่าครอบครัว</div><h2 style="margin-top:20px">ยินดีต้อนรับเข้าสู่บ้านของเรา</h2><p class="muted">สร้างสมุดบันทึกครอบครัวใหม่ หรือใช้อีเมลบัญชีนี้ให้สมาชิกที่สร้างครอบครัวแล้วส่งคำเชิญ</p><div class="field"><label>โหมดใช้งานของบัญชีนี้</label><select id="firstRole"><option value="mother">คุณแม่ · เน้นบันทึกอาการและลูกดิ้น</option><option value="father">คุณพ่อ · เน้นติดตามนัดและการเตรียมของ</option></select></div><button class="btn" data-act="create-family" style="width:100%;margin-top:13px">${ico('home')} สร้างครอบครัวใหม่</button><div class="notice" style="margin:18px 0">หากอีกฝ่ายสร้างครอบครัวไว้แล้ว ให้แจ้งเขากด “เชิญสมาชิก” และกรอกอีเมลที่ใช้บัญชีนี้ แล้วกลับมาเปิดหน้าอีกครั้ง</div><button class="btn btn-light" data-act="reload-family" style="width:100%">${ico('refresh-cw')} ตรวจสอบคำเชิญ</button><button class="text-link" data-act="logout" style="margin:20px auto 0">ออกจากระบบ</button></div></div>`;iconize()}
async function createFamily(){try{const role=$('#firstRole')?.value||'mother',r=await db.rpc('create_family',{p_title:'Our Little Family'});if(r.error)throw r.error;const settings={...initial().settings,userRoles:{[state.user.id]:role}};const x=await db.rpc('pmp_merge_settings',{p_family:r.data,p_patch:settings});if(x.error)throw x.error;for(const [category,title] of presetTasks){const add=await db.rpc('pmp_add_item',{p_family:r.data,p_collection:'tasks',p_item:{id:oid(),title,category,done:false,createdAt:new Date().toISOString()}});if(add.error)throw add.error}await loadFamily();toast('สร้างครอบครัวสำเร็จ')}catch(err){toast(err.message,true)}}
async function mergeSettings(patch){if(state.demo){state.data.settings={...state.data.settings,...patch};render();return true}let r=await db.rpc('pmp_merge_settings',{p_family:state.family.id,p_patch:patch});if(r.error){toast(r.error.message,true);return false}await loadFamily();return true}
async function addItem(coll,item){const value={id:oid(),createdAt:new Date().toISOString(),createdBy:state.user?.id||null,...item};if(state.demo){state.data[coll].push(value);render();return true}const {error}=await db.rpc('pmp_add_item',{p_family:state.family.id,p_collection:coll,p_item:value});if(error){toast(error.message,true);return false}await refresh();return true}
async function patchItem(coll,id,patch){if(state.demo){const item=arr(coll).find(x=>x.id===id);if(item)Object.assign(item,patch);render();return true}const {error}=await db.rpc('pmp_update_item',{p_family:state.family.id,p_collection:coll,p_item_id:id,p_patch:patch});if(error){toast(error.message,true);return false}await refresh();return true}
async function removeItem(coll,id){if(state.demo){state.data[coll]=arr(coll).filter(x=>x.id!==id);render();return}const {error}=await db.rpc('pmp_remove_item',{p_family:state.family.id,p_collection:coll,p_item_id:id});if(error)return toast(error.message,true);await refresh()}
async function refreshPhotoUrls(){state.mediaUrls={};if(state.demo||!db)return;const photos=arr('photos').filter(x=>x.path);await Promise.all(photos.map(async x=>{const {data}=await db.storage.from('pregnancy-media').createSignedUrl(x.path,3600);if(data?.signedUrl)state.mediaUrls[x.id]=data.signedUrl}))}
async function uploadPhoto(file,type,caption,takenAt,extra={}){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('รองรับภาพ JPG, PNG, WEBP เท่านั้น',true);if(file.size>12*1024*1024)return toast('ภาพต้องมีขนาดไม่เกิน 12 MB',true);
const id=oid(),ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=`${state.family.id}/${id}.${ext}`;
if(state.demo){const url=URL.createObjectURL(file);state.data.photos.push({id,category:type,caption,takenAt,...extra,path:'',createdAt:new Date().toISOString()});state.mediaUrls[id]=url;render();toast('เพิ่มภาพตัวอย่างแล้ว (ไม่ถูกบันทึกถาวร)');return}
const {error:up}=await db.storage.from('pregnancy-media').upload(path,file,{contentType:file.type,upsert:false});if(up)throw up;
const {error}=await db.rpc('pmp_add_item',{p_family:state.family.id,p_collection:'photos',p_item:{id,category:type,caption,takenAt,...extra,path,createdAt:new Date().toISOString(),createdBy:state.user?.id||null}});
if(error){await db.storage.from('pregnancy-media').remove([path]);throw error}await refresh();toast('เพิ่มภาพลงอัลบั้มแล้ว')}
const nav=[['home','layout-dashboard','ภาพรวม'],['journey','heart-pulse','สุขภาพ'],['plan','list-checks','เตรียมพร้อม'],['photos','images','ความทรงจำ'],['settings','settings-2','ตั้งค่า']];
function render(){const selected=nav.find(x=>x[0]===state.tab)||nav[0];APP.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-icon">${ico('heart-handshake')}</div><div>Pregnant Manager<span class="brand-sub">PRO · FAMILY JOURNAL</span></div></div><div><div class="side-label">YOUR LITTLE JOURNEY</div>${nav.map(([id,sym,txt])=>`<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}">${ico(sym)} ${txt}</button>`).join('')}</div><div class="side-bottom"><span class="pill">${ico('lock-keyhole')} Private Family Space</span><p>ภาพและข้อมูลสุขภาพจัดเก็บเป็นส่วนตัว แชร์กับสมาชิกครอบครัวที่ได้รับเชิญเท่านั้น</p><button class="text-link" data-act="lock">${ico('lock')} ล็อกหน้าจอ</button></div></aside><div class="main"><div class="shell">${state.demo?'<div class="demo-banner">✦ DEMO MODE — ข้อมูลทดลองไม่ถูกบันทึกลงฐานข้อมูล</div>':''}<div class="topbar"><div><div class="eyebrow">${esc(titleDate())}</div><div class="page-title">${esc(selected[2])}</div></div><div class="actions"><button class="icon-btn" title="ล็อกหน้าจอ" data-act="lock">${ico('lock-keyhole')}</button><button class="avatar" title="เปลี่ยนโหมดได้ในการตั้งค่า" data-tab="settings">${ico(state.role==='mother'?'flower-2':'user-round')}</button></div></div>${({home:pageHome,journey:pageJourney,plan:pagePlan,photos:pagePhotos,settings:pageSettings}[state.tab]||pageHome)()}<div class="footer-disclaimer">Pregnant Manager Pro เป็นเครื่องมือจดบันทึก ไม่ใช่การวินิจฉัยหรือทดแทนสมุดสีชมพูและการดูแลจากแพทย์</div></div></div><nav class="mobile-nav">${nav.map(([id,sym,txt])=>`<button class="${state.tab===id?'active':''}" data-tab="${id}">${ico(sym)}<span>${txt}</span></button>`).join('')}</nav></div>`;iconize();}
function section(title,moreLabel,action){return `<div class="section-head"><h2>${title}</h2>${action?`<button class="text-link" data-act="${action}">${esc(moreLabel)} ${ico('arrow-up-right')}</button>`:''}</div>`}
function empty(title,icon='notebook-pen'){return `<div class="list-empty">${ico(icon)}<div>${esc(title)}</div></div>`}
function buttonAction(act,symbol,text,description){return `<button class="quick-card" data-act="${act}"><div><div class="quick-icon">${ico(symbol)}</div><h3>${esc(text)}</h3><p>${esc(description)}</p></div><span class="quick-arrow">${ico('arrow-up-right')}</span></button>`}
function hero(){const p=pregnancy(),born=isBorn(),s=state.data.settings,b=babyIdentity();return `<section class="hero"><div class="hero-content"><div class="eyebrow">${born?'CHAPTER 02 / OUR BABY':'CHAPTER 01 / EXPECTING YOU'}</div><h1 class="hero-title">${born?`${esc(b.displayEn)}<br><span>is here.</span>`:p?`Week ${p.weeks}<span> + ${p.remainder}</span>`:'Our little<br><span>miracle.</span>'}</h1><p class="hero-copy">${born?`บันทึกทุกช่วงเวลาหลังคลอดของ${esc(b.displayTh)} · อายุ ${daysBaby()} วัน`:b.known?`การเดินทางของ${esc(b.displayTh)} ♡ ทุกก้าวเล็ก ๆ มีความหมายต่อครอบครัวเรา`:'ทุกก้าวเล็ก ๆ ของการเดินทางที่มีความหมายที่สุดของครอบครัวเรา'}</p>${b.known?`<div class="baby-hero-name">${ico('heart')} <span>${esc(b.displayTh)}</span><small>${esc(b.english||b.sexLabel)}</small></div>`:''}<div class="hero-stats"><div class="hero-stat"><b>${born?fmtDate(s.birthDate):p?`${p.weeks}w ${p.remainder}d`:'—'}</b><small>${born?'วันเกิดของลูก':'อายุครรภ์ประมาณ'}</small></div><div class="hero-stat"><b>${born?`${daysBaby()} วัน`:p?`${Math.max(0,p.left)} วัน`:'—'}</b><small>${born?'อายุหลังคลอด':'จนถึงกำหนดคลอด (โดยประมาณ)'}</small></div></div>${!born?`<div class="hero-progress"><div class="track"><div class="fill" style="width:${p?p.pct:0}%"></div></div><div class="hero-foot"><span>${p?Math.round(p.pct)+'% ของ 40 สัปดาห์':'กรอกกำหนดคลอดเพื่อเริ่มคำนวณ'}</span><span>EDD ${s.dueDate?fmtDate(s.dueDate):'ยังไม่กำหนด'}</span></div></div>`:`<span class="pill" style="background:#f3e6f6;color:#846d98">${ico('sparkles')} เริ่มบทใหม่ของครอบครัว</span>`}</div><div class="hero-art"><span class="sparkle a">✧</span><div class="moon"><div class="moon-inner">${born?'🧸':'♡'}</div><div class="moon-label">${esc(b.known&&b.english?b.english:'HELLO LITTLE ONE')}</div></div><span class="sparkle b">✦</span></div></section>`}
function upcoming(){return [...arr('appointments')].filter(a=>a.status!=='done'&&new Date(a.at)>=new Date(Date.now()-86400000)).sort((a,b)=>a.at.localeCompare(b.at))}
function apptView(a){const d=new Date(a.at);const addlink=calendarURL(a);return `<div class="appointment"><div class="date-square"><b>${d.getDate()}</b><small>${d.toLocaleDateString('th-TH',{month:'short'})}</small></div><div class="appointment-copy"><b>${esc(a.title||'นัดหมาย')}</b><p>${ico('map-pin')} ${esc(a.place||'ยังไม่ระบุสถานที่')} ${a.doctor?'· '+esc(a.doctor):''}</p><p>${esc(a.purpose||'')}</p></div><div class="appt-right"><b>${fmtTime(a.at)}</b><div style="margin-top:6px"><a href="${esc(addlink)}" target="_blank" rel="noopener noreferrer" class="text-link" title="เพิ่มลง Google Calendar">${ico('calendar-plus')}</a></div></div></div>`}
function chart(series,color='#a785bc',height=135){const nums=series.map(x=>Number(x.value)).filter(Number.isFinite);if(!nums.length)return empty('เริ่มบันทึกเพื่อสร้างกราฟแนวโน้ม','chart-no-axes-column');const W=360,H=height,p=17,min=Math.min(...nums),max=Math.max(...nums),range=Math.max(max-min,1),points=nums.map((y,i)=>[p+(nums.length===1?0:i*(W-2*p)/(nums.length-1)),H-p-(y-min)/range*(H-2*p)]);return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="แนวโน้มจากข้อมูลที่บันทึก"><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="#efe6f0"/><line x1="${p}" y1="${p}" x2="${W-p}" y2="${p}" stroke="#efe6f0"/><polyline fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${points.map(q=>q.join(',')).join(' ')}"/>${points.map(q=>`<circle cx="${q[0]}" cy="${q[1]}" r="4" fill="#fff" stroke="${color}" stroke-width="2"/>`).join('')}</svg><div class="micro">${esc(String(min))}–${esc(String(max))} · ${nums.length} รายการ · ไม่ใช่กราฟวินิจฉัย</div>`}
function statCards(){const total=arr('tasks').length,done=arr('tasks').filter(x=>x.done).length,appts=upcoming().length,photos=arr('photos').length;return `<div class="grid-3 stat-cards"><div class="card kpi"><span class="pill">${ico('calendar-clock')} นัดหมาย</span><div class="metric">${appts}</div><small>นัดที่กำลังจะมาถึง</small></div><div class="card kpi"><span class="pill">${ico('list-checks')} เช็กลิสต์</span><div class="metric">${done}<span class="micro"> / ${total}</span></div><small>รายการที่เตรียมเสร็จ</small></div><div class="card kpi"><span class="pill">${ico('images')} อัลบั้ม</span><div class="metric">${photos}</div><small>ภาพความทรงจำ</small></div></div>`}
function pageHome(){const born=isBorn(),log=ordered(born?'babyLogs':'symptoms').slice(0,7),chartData=log.slice().reverse().filter(x=>x.mood).map(x=>({value:x.mood}));return `<div class="home-greeting"><div><span class="home-greeting__eyebrow">${ico('sun-medium')} A BEAUTIFUL DAY TO REMEMBER</span><p>วันนี้มีเรื่องราวดี ๆ อะไรบ้างนะ <span>♡</span></p></div><div class="home-greeting__badge">${ico('heart')} ${state.role==='mother'?'MOM MODE':'DAD MODE'}</div></div>${hero()}${babyIdentity().known?'':`<div class="baby-gender-prompt">${ico('sparkles')} <span>ทราบเพศลูกจากผลตรวจแล้วหรือยัง? เลือกเพศเพื่อให้แอปเรียกชื่อที่ตั้งไว้ได้อัตโนมัติ</span><button type="button" data-tab="settings">ตั้งค่าชื่อลูก ${ico('arrow-right')}</button></div>`}${v7Home()}${section('ทางลัดสำหรับ'+(state.role==='mother'?'คุณแม่':'คุณพ่อ'))}<div class="grid-3">${born?buttonAction('baby-log','baby','บันทึกลูกวันนี้','นม · นอน · ผ้าอ้อม'):(state.role==='mother'?buttonAction('kick','heart-pulse','นับลูกดิ้น','บันทึกการเคลื่อนไหว'):buttonAction('appointment','calendar-plus','เพิ่มนัดแพทย์','ติดตามทุกการตรวจ'))}${born?buttonAction('growth','ruler','การเติบโต','น้ำหนักและความยาว'):buttonAction('symptom','notebook-pen','บันทึกอาการ','บันทึกความรู้สึกวันนี้')}${buttonAction('photo','camera','เพิ่มรูปภาพ','ภาพครอบครัวและอัลตราซาวด์')}</div>${section('ภาพรวมครอบครัว')}${statCards()}<div class="grid-2" style="margin-top:16px"><div class="card"><div class="section-head" style="margin:0 0 9px"><h3>นัดหมายใกล้ถึง</h3><button class="text-link" data-act="appointment">${ico('plus')} เพิ่ม</button></div>${upcoming().length?upcoming().slice(0,3).map(apptView).join(''):empty('ยังไม่มีนัดหมายที่กำลังจะมาถึง','calendar-check')}</div><div class="card"><div class="section-head" style="margin:0 0 9px"><h3>${born?'สรุปบันทึกประจำวัน':'อารมณ์ช่วงที่ผ่านมา'}</h3><button class="text-link" data-tab="journey">ดูทั้งหมด ${ico('arrow-up-right')}</button></div>${chart(chartData)}<div class="notice" style="margin-top:18px">กราฟแสดงแนวโน้มจากค่าที่กรอกเอง ไม่สามารถสรุปภาวะสุขภาพหรือความปลอดภัยของการตั้งครรภ์ได้</div></div></div>${!born?`<div class="notice warn" style="margin-top:17px">${ico('info')} หากลูกเคลื่อนไหวน้อยลง หยุดดิ้น หรือรูปแบบเปลี่ยนจากปกติ ควรติดต่อหน่วยฝากครรภ์/ห้องคลอดทันที ไม่ต้องรอให้นับครบจำนวนใด</div>`:''}${!state.data.settings.dueDate&&!born?`<div class="notice" style="margin-top:14px">ยังไม่ได้ใส่กำหนดคลอด <button class="text-link" data-act="edit-family" style="display:inline">ตั้งค่าตอนนี้</button></div>`:''}`}
// Device PINs are only a convenience lock, never a replacement for Supabase Auth/RLS.
// PIN is a convenience screen-lock for a VALID Supabase session, not account authentication.
// Stored as a salted slow KDF only; no raw PIN, Supabase password or medical data in PIN storage.
const pinKey=()=>`pmp-profiles-${state.user?.id||'demo'}`;
const pinProfiles=()=>{try{const obj=JSON.parse(localStorage.getItem(pinKey())||'{}');return obj&&typeof obj==='object'&&!Array.isArray(obj)?obj:{}}catch{return {}}};
const pinRateKey=()=>`pmp-pin-rate-${state.user?.id||'demo'}-${state.role}`;
const pinRate=()=>{try{return JSON.parse(localStorage.getItem(pinRateKey())||'{}')}catch{return {}}};
function pinBlocked(){const r=pinRate();return Number(r.until||0)>Date.now()}
function pinReject(){const r=pinRate(),tries=(Number(r.tries)||0)+1,until=tries>=5?Date.now()+Math.min(30*60*1000,60000*Math.pow(2,Math.floor((tries-5)/5))):0;localStorage.setItem(pinRateKey(),JSON.stringify({tries,until}));return until}
function clearPinRate(){localStorage.removeItem(pinRateKey())}
async function digestPin(pin,salt){const bytes=new TextEncoder().encode(`${salt}:${pin}`),hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function securePin(pin,salt,iterations=310000){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const out=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations,hash:'SHA-256'},key,256);return [...new Uint8Array(out)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function timingSafeEqualHex(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
// Each device remembers only its last successfully unlocked profile. Never cache the raw PIN.
const lastRoleKey=()=>`pmp-role-${state.user?.id||'demo'}`;
const rememberedRole=()=>{const r=localStorage.getItem(lastRoleKey());return r==='mother'||r==='father'?r:null};
function parentPortrait(role){return role==='father'?`<svg viewBox="0 0 120 120" width="100" height="100" aria-hidden="true"><circle cx="60" cy="60" r="58" fill="#e5eefc"/><path d="M17 112c4-24 21-36 43-36s39 12 43 36" fill="#86a9d5"/><path d="M49 79h22v15H49z" fill="#edbfa4"/><ellipse cx="60" cy="48" rx="25" ry="31" fill="#f0c6aa"/><path d="M34 46c-1-23 11-34 28-34 19 0 29 13 24 33l-7-9c-16 1-28-4-39-2z" fill="#594e5e"/><circle cx="51" cy="50" r="2" fill="#66545a"/><circle cx="69" cy="50" r="2" fill="#66545a"/><path d="M54 65q6 5 12 0" fill="none" stroke="#bb8f84" stroke-width="2" stroke-linecap="round"/></svg>`:`<svg viewBox="0 0 120 120" width="100" height="100" aria-hidden="true"><circle cx="60" cy="60" r="58" fill="#f9e7ef"/><path d="M20 112c2-23 21-37 40-37s38 14 40 37" fill="#d6a2bf"/><path d="M31 52c-3-30 11-42 29-42 21 0 33 14 30 44l-9 28H39z" fill="#604b5f"/><ellipse cx="60" cy="50" rx="24" ry="30" fill="#f3c8ae"/><path d="M36 41c3-28 19-33 26-33 14 0 23 11 23 34l-9-13c-13 6-26 9-40 12" fill="#604b5f"/><path d="M49 79h22v15H49z" fill="#efbea5"/><circle cx="51" cy="51" r="2" fill="#66545a"/><circle cx="69" cy="51" r="2" fill="#66545a"/><path d="M54 65q6 5 12 0" fill="none" stroke="#bb8f84" stroke-width="2" stroke-linecap="round"/></svg>`}
function renderPin(){MOD.innerHTML='';const remembered=rememberedRole(),switching=state.pendingRole==='mother'||state.pendingRole==='father';if(switching)state.role=state.pendingRole;else if(remembered)state.role=remembered;const profiles=pinProfiles(),record=profiles[state.role],has=Object.keys(profiles).length>0,setup=!record,blocked=pinBlocked(),single=!!remembered||switching;const digits=Array.from({length:6},()=>'<span class="pmp-pin-dot"></span>').join('');const roleIsDad=state.role==='father';const profileDisplay=single?`<div class="pmp-remembered-profile ${roleIsDad?'is-dad':'is-mom'}" aria-label="โปรไฟล์ที่จำไว้ ${roleIsDad?'คุณพ่ออาร์':'คุณแม่เอมมี่'}"><div class="pmp-single-portrait">${parentPortrait(state.role)}</div><span class="pmp-profile-label">${switching?'SWITCH PROFILE':'LAST USED PROFILE'}</span><strong>${roleIsDad?'คุณพ่อ':'คุณแม่'}</strong><span class="pmp-profile-nickname">${roleIsDad?'อาร์':'เอมมี่'}</span><span class="pmp-remembered-chip">${ico(switching?'lock-keyhole':'check-circle-2')} ${switching?'ยืนยัน PIN เพื่อสลับโปรไฟล์':'โปรไฟล์ประจำเครื่องนี้'}</span></div>`:`<div class="pmp-profile-pair" aria-label="เลือกโปรไฟล์ครั้งแรก"><button type="button" class="pmp-profile-choice pmp-profile-mom ${state.role==='mother'?'selected':''}" data-pick-role="mother"><span class="pmp-profile-icon">${ico('flower-2')}</span><b>คุณแม่</b><small>เอมมี่</small></button><button type="button" class="pmp-profile-choice pmp-profile-dad ${state.role==='father'?'selected':''}" data-pick-role="father"><span class="pmp-profile-icon">${ico('user-round')}</span><b>คุณพ่อ</b><small>อาร์</small></button></div>`;APP.innerHTML=`<div class="auth-frame pmp-pin-screen"><div class="auth-card pmp-pin-card"><div class="pmp-pin-mark">${ico('heart-handshake')}</div><div class="eyebrow" style="text-align:center">PRIVATE FAMILY SPACE</div><h1 class="pmp-pin-title">${single?`ยินดีต้อนรับ${roleIsDad?'คุณพ่อ':'คุณแม่'}`:has?'ยินดีต้อนรับกลับบ้าน':'ตั้งรหัสของครอบครัว'} <span>♡</span></h1><p class="pmp-pin-lead">${single?'กรอก PIN เพื่อเปิดสมุดของครอบครัวได้เลย':has?'เลือกโปรไฟล์ของคุณและกรอก PIN':'เลือกคุณพ่อหรือคุณแม่ แล้วตั้ง PIN ครั้งแรกบนเครื่องนี้'}</p>${profileDisplay}<div class="pmp-pin-entry"><div class="pmp-pin-caption">${setup?'CREATE YOUR 6-DIGIT PIN':'ENTER YOUR 6-DIGIT PIN'}</div><form id="pinForm" autocomplete="off"><label class="pmp-pin-visually-hidden" for="pmpPinInput">${setup?'ตั้ง PIN 6 หลัก':'กรอก PIN 6 หลัก'}</label><input id="pmpPinInput" class="pmp-pin-input" name="pin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" minlength="6" required aria-label="PIN หกหลัก"><div class="pmp-pin-dots" aria-hidden="true">${digits}</div>${setup?`<div class="pmp-pin-confirm"><label>ยืนยัน PIN อีกครั้ง</label><input id="pmpPinConfirm" name="confirm" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" minlength="6" required placeholder="กรอก PIN อีกครั้ง"></div>`:''}<div class="pmp-keypad">${['1','2','3','4','5','6','7','8','9','clear','0','back'].map(d=>`<button type="button" data-pin-digit="${d}" aria-label="${d==='clear'?'ล้างเลข':d==='back'?'ลบเลข':d}" class="${d==='clear'||d==='back'?'pmp-keypad-alt':''}">${d==='clear'?ico('rotate-ccw'):d==='back'?ico('delete'):d}</button>`).join('')}</div><button class="btn pmp-pin-submit" type="submit" ${blocked?'disabled':''}>${ico(setup?'shield-check':'unlock-keyhole')} ${setup?'บันทึก PIN และเปิดสมุด':'ปลดล็อกสมุดของเรา'}</button></form>${blocked?`<p class="pmp-pin-error" role="alert">ลอง PIN ผิดหลายครั้ง กรุณารอ ${Math.max(1,Math.ceil((pinRate().until-Date.now())/60000))} นาที หรือยืนยันบัญชีอีกครั้ง</p>`:''}</div><p class="pmp-pin-footer">${ico('shield-check')} PIN นี้ใช้ล็อกหน้าจอบนอุปกรณ์ ไม่ได้แทน Supabase Auth และไม่มีการเก็บ PIN เป็นตัวเลขดิบ</p><button class="text-link pmp-pin-recover" data-act="recover-pin">${ico('key-round')} ลืม PIN / เปลี่ยนอุปกรณ์? ยืนยันบัญชีใหม่</button></div></div>`;iconize();$('#pinForm').onsubmit=submitPin;$('#pmpPinInput')?.addEventListener('input',updatePinDots);updatePinDots()}
function renderPinForSwitch(role){state.pendingRole=role;state.role=role;renderPin()}
function updatePinDots(){const inp=$('#pmpPinInput');if(!inp)return;inp.value=inp.value.replace(/\D/g,'').slice(0,6);document.querySelectorAll('.pmp-pin-dot').forEach((d,i)=>d.classList.toggle('filled',i<inp.value.length))}
async function submitPin(e){e.preventDefault();if(state.pinBusy)return;const form=e.currentTarget,d=new FormData(form),pin=String(d.get('pin')||''),profiles=pinProfiles(),record=profiles[state.role];if(!/^\d{6}$/.test(pin))return toast('กรอก PIN 6 หลัก',true);if(pinBlocked())return toast('ลอง PIN ผิดหลายครั้ง กรุณารอสักครู่',true);state.pinBusy=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{if(record){const attempts=Number(record.iterations)||150000,computed=record.alg==='pbkdf2'?await securePin(pin,record.salt,attempts):await digestPin(pin,record.salt);if(!timingSafeEqualHex(computed,record.hash)){const until=pinReject();form.reset();updatePinDots();toast(until?'ลองผิดหลายครั้ง ระบบพักการปลดล็อกชั่วคราว':'PIN ไม่ถูกต้อง',true);if(until)renderPin();return}if(record.alg!=='pbkdf2'||attempts<310000){const salt=crypto.randomUUID();profiles[state.role]={salt,hash:await securePin(pin,salt),alg:'pbkdf2',iterations:310000};localStorage.setItem(pinKey(),JSON.stringify(profiles))}}else{if(pin!==String(d.get('confirm')||''))return toast('ยืนยัน PIN ไม่ตรงกัน',true);const salt=crypto.randomUUID();profiles[state.role]={salt,hash:await securePin(pin,salt),alg:'pbkdf2',iterations:310000};localStorage.setItem(pinKey(),JSON.stringify(profiles))}clearPinRate();localStorage.setItem(lastRoleKey(),state.role);state.pendingRole=null;state.unlocked=state.user.id;state.lastActivity=Date.now();if(state.demo){render()}else{const {data:{user},error}=await db.auth.getUser();if(error||!user||user.id!==state.user.id){state.unlocked=null;renderWelcome();return toast('เซสชันหมดอายุ กรุณาใช้ Passkey หรือเข้าสู่ระบบใหม่',true)}await loadFamily()}toast(`เข้าใช้งานโหมด${state.role==='mother'?'คุณแม่':'คุณพ่อ'}แล้ว`)}catch(err){console.error('PIN unlock',err);toast('ไม่สามารถปลดล็อกได้ กรุณาลองอีกครั้ง',true)}finally{state.pinBusy=false;if(submit?.isConnected)submit.disabled=false}}
function showModal(title,inner,submitText='บันทึก'){MOD.innerHTML=`<div class="modal-backdrop" data-close="1"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" type="button" data-close="1">${ico('x')}</button></div><form id="entryForm"><div class="modal-body">${inner}</div><div class="modal-foot"><button type="button" class="btn btn-light" data-close="1">ยกเลิก</button><button class="btn" type="submit">${esc(submitText)}</button></div></form></div></div>`;iconize()}
const field=(label,name,type='text',value='',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const area=(label,name)=>`<div class="field"><label>${label}</label><textarea name="${name}" rows="3"></textarea></div>`;
const formValues=e=>Object.fromEntries(new FormData(e.currentTarget).entries());
function v7JourneyOverview(){const born=isBorn();return `<div class="page-intro journey-intro"><span class="page-intro__icon">${ico('heart-pulse')}</span><div><span>WELLNESS & LITTLE MOMENTS</span><h2>ทุกวันคืออีกหนึ่งความทรงจำ</h2><p>บันทึกอย่างสม่ำเสมอเพื่อทบทวนข้อมูลกับทีมฝากครรภ์</p></div></div><div class="card"><h2>${born?'สมุดสุขภาพลูก':'บันทึกการตั้งครรภ์'}</h2><div class="grid-3">${buttonAction(born?'baby-log':'kick','heart-pulse',born?'บันทึกนมและการนอน':'เริ่มนับลูกดิ้น','บันทึกข้อมูลอย่างรวดเร็ว')}${buttonAction('symptom','notebook-pen','บันทึกอาการคุณแม่','ติดตามความรู้สึกและอาการ')}${buttonAction('appointment','calendar-plus','เพิ่มนัดแพทย์','รายละเอียดการตรวจและสถานที่')}</div>${section('บันทึกล่าสุด')}${ordered(born?'babyLogs':'symptoms').slice(0,15).map(x=>`<div class="record">${esc(fmtDate(x.date||x.createdAt))} · ${esc(x.note||x.type||'บันทึก')}</div>`).join('')||empty('ยังไม่มีรายการ')}</div><div class="card" style="margin-top:18px"><h3>ประวัติการนับลูกดิ้น</h3>${ordered('kicks').slice(0,15).map(x=>`<div class="record">${fmtDate(x.createdAt)} · ${esc(x.count)} ครั้ง · ${esc(x.minutes)} นาที</div>`).join('')||empty('ยังไม่ได้บันทึก','heart-pulse')}<p class="micro">จำนวนการดิ้นไม่ใช่การยืนยันว่าทารกปลอดภัย หากดิ้นน้อยลงหรือเปลี่ยนไปจากปกติให้ติดต่อโรงพยาบาลทันที</p></div>`}
function pageJourney(){const views={overview:v7JourneyOverview,pink:v7Pink,analytics:v7Analytics,newborn:v7Newborn,vaccines:v7Vaccines};return v7CareTabs()+(views[state.careTab]||v7JourneyOverview)()}
function pagePlan(){const tasks=arr('tasks'),total=tasks.length,done=tasks.filter(x=>x.done).length,pct=total?Math.round(done/total*100):0,order=['hospital','baby','home','parent','other'],catIcons={hospital:'briefcase-medical',baby:'baby',home:'house-heart',parent:'heart-handshake',other:'sparkles'};const categoryCards=order.map(key=>{const items=tasks.filter(t=>(t.category||'other')===key),complete=items.filter(t=>t.done).length;return items.length?`<div class="checklist-cat checklist-cat--${key}"><div class="checklist-cat__icon">${ico(catIcons[key]||'sparkles')}</div><div><span>${esc(catLabels[key]||'อื่น ๆ')}</span><strong>${complete}<small> / ${items.length}</small></strong></div></div>`:''}).join('');const grouped=order.map(key=>{const items=tasks.filter(t=>(t.category||'other')===key);if(!items.length)return '';const complete=items.filter(t=>t.done).length,cpct=Math.round(complete/items.length*100);return `<section class="task-section task-section--${key}"><div class="task-section__head"><div><span>${esc(catLabels[key]||'อื่น ๆ')}</span><h3>${complete===items.length?'พร้อมแล้วทั้งหมด':'ค่อย ๆ เตรียมไปทีละอย่าง'}</h3></div><div class="task-section__meta"><strong>${complete}/${items.length}</strong><small>${cpct}% complete</small></div></div><div class="task-mini-progress"><span style="width:${cpct}%"></span></div><div class="task-stack">${items.map(t=>`<label class="task-card ${t.done?'is-done':''}"><input type="checkbox" data-task-id="${esc(t.id)}" ${t.done?'checked':''}><span class="task-card__body"><b>${esc(t.title)}</b><small>${esc(catLabels[t.category]||'อื่น ๆ')}</small></span><span class="task-card__tick">${t.done?ico('check'):ico('circle')}</span></label><button type="button" class="v7-task-edit" data-task-edit="${esc(t.id)}">${ico('wallet')} แก้ไขงบ · ${v7money(t.spent||t.budget||0)}</button>`).join('')}</div></section>`}).join('');return `<div class="page-intro plan-intro"><span class="page-intro__icon">${ico('clipboard-check')}</span><div><span>PREPARING FOR YOU</span><h2>จัดเตรียมทุกอย่างด้วยความรัก</h2><p>ค่อย ๆ เตรียมไปทีละอย่าง ไม่มีอะไรต้องเร่งรีบ</p></div></div><div class="checklist-summary"><div><span>OUR PROGRESS</span><strong>${done}<small> / ${total} รายการ</small></strong><p class="checklist-summary__caption">จากลิสต์ทั้งหมดที่ครอบครัววางไว้สำหรับการต้อนรับลูกน้อย</p></div><div class="checklist-summary__ring" style="--percent:${pct}%"><span>${pct}%</span></div><div class="checklist-summary__track"><span style="width:${pct}%"></span></div></div>${v7ShoppingList()}${categoryCards?`<div class="checklist-cats">${categoryCards}</div>`:''}<div class="card checklist-board"><div class="section-head"><div><h2>Baby preparation checklist</h2><p class="muted" style="margin:6px 0 0">จัดลิสต์ของจำเป็นให้เป็นระเบียบและติ๊กได้ง่ายบนมือถือ</p></div><button class="btn" data-act="task">${ico('plus')} เพิ่มรายการ</button></div>${grouped||empty('ยังไม่มีรายการ','clipboard-list')}</div><div class="card" style="margin-top:18px"><div class="section-head"><h2>นัดหมายแพทย์</h2><button class="btn btn-light" data-act="appointment">${ico('calendar-plus')} เพิ่มนัด</button></div>${upcoming().map(apptView).join('')||empty('ยังไม่มีนัดหมาย')}</div>`}
function pagePhotos(){const photos=ordered('photos'),shown=state.galleryTab==='all'?photos:photos.filter(x=>x.category===state.galleryTab);return `<div class="page-intro gallery-intro"><span class="page-intro__icon">${ico('images')}</span><div><span>FAMILY MEMORY BOOK</span><h2>เรื่องราวที่อยากเก็บไว้ตลอดไป</h2><p>ภาพอัลตราซาวด์ ภาพคุณแม่รายเดือน และจดหมายถึงลูกในอนาคต</p></div></div>${v7Bump()}<section class="v7-surface" style="margin-top:16px"><div class="v7-header-row"><div><span class="v7-kicker">PRIVATE FAMILY GALLERY</span><h2>อัลบั้มความทรงจำ</h2></div>${v7btn('photo','camera','เพิ่มภาพ')}</div><div class="v7-tabs" role="tablist">${[['all','ทั้งหมด'],['family','ครอบครัว'],['bump','คุณแม่'],['ultrasound','อัลตราซาวด์'],['milestone','ช่วงเวลา'],['health','เอกสาร']].map(([k,t])=>`<button type="button" data-gallery="${k}" class="${state.galleryTab===k?'active':''}">${esc(t)}</button>`).join('')}</div><div class="photo-grid">${shown.map(p=>`<div class="photo-tile"><button type="button" data-view-photo="${esc(p.id)}" class="v7-photo-open" aria-label="ดูภาพเต็ม">${ico('expand')}</button>${state.mediaUrls[p.id]?`<img loading="lazy" src="${esc(state.mediaUrls[p.id])}" alt="${esc(p.caption||photoTypes[p.category]||'ภาพครอบครัว')}">`:`<div class="empty-photo">${ico('image')}</div>`}<div><b>${esc(p.caption||photoTypes[p.category]||'ภาพ')}</b><small>${p.category==='bump'&&p.month?'เดือนที่ '+esc(p.month)+' · ':''}${v7date(p.takenAt)}</small>${p.week?`<small>อายุครรภ์ประมาณ ${esc(p.week)} สัปดาห์</small>`:''}${p.note?`<small>${esc(p.note)}</small>`:''}</div></div>`).join('')}</div>${shown.length?'':empty('ยังไม่มีภาพในอัลบั้มนี้')}</section><div style="margin-top:16px">${v7Memories()}</div>`}
 function pageSettings(){const s=state.data.settings,role=state.role==='mother',b=babyIdentity(),gender=b.sexLabel;return `
 <div class="settings-cover">
   <div class="settings-cover__copy"><span class="settings-kicker">${ico('sparkles')} FAMILY SPACE · OUR LITTLE WORLD</span><h2>บ้านหลังเล็ก<br><em>ของเรา ♡</em></h2><p>เก็บทุกเรื่องราวของครอบครัวไว้ในที่เดียว ตั้งแต่วันแรกที่รู้ว่ามีเจ้าตัวเล็ก</p><span class="settings-cover__note">${ico('shield-check')} พื้นที่ส่วนตัวสำหรับสมาชิกครอบครัว</span></div>
   <div class="settings-cover__art" aria-hidden="true"><span class="cover-orbit orbit-one"></span><span class="cover-orbit orbit-two"></span><span class="cover-big-heart">♡</span><span class="cover-spark">✳</span><span class="cover-star">✦</span></div>
 </div>
 <div class="settings-grid">
 <section class="settings-panel settings-family"><div class="panel-heading"><span class="panel-icon rose">${ico('users-round')}</span><div><span class="panel-eyebrow">01 · OUR FAMILY</span><h2>ครอบครัวของเรา</h2></div></div>
 <div class="family-people"><div class="family-person"><div class="person-avatar mama">${ico('flower-2')}</div><div class="person-details"><span>คุณแม่ · ${esc(s.motherNick||'เอมมี่')}</span><strong>${esc(s.mother)}</strong></div><span class="person-heart">♡</span></div><div class="family-person"><div class="person-avatar papa">${ico('user-round')}</div><div class="person-details"><span>คุณพ่อ · ${esc(s.fatherNick||'อาร์')}</span><strong>${esc(s.father)}</strong></div><span class="person-heart">♡</span></div></div>
 <div class="due-preview"><div class="due-icon">${ico('calendar-heart')}</div><div><span>วันกำหนดคลอดโดยประมาณ</span><strong>${fmtDate(s.dueDate)}</strong></div>${ico('sparkles')}</div>
 <button class="btn settings-main-action" data-act="edit-family">${ico('pencil-line')} แก้ไขข้อมูลครอบครัว ${ico('arrow-up-right')}</button></section>
 <section class="settings-panel settings-profile"><div class="panel-heading"><span class="panel-icon lilac">${ico('scan-face')}</span><div><span class="panel-eyebrow">02 · ACCESS & PROFILES</span><h2>PIN & โปรไฟล์</h2></div></div>
 <div class="active-profile"><div class="active-profile__bubble ${role?'pink':'blue'}">${ico(role?'flower-2':'user-round')}</div><div><span>กำลังใช้งานในโหมด</span><strong>${role?'คุณแม่ · เอมมี่':'คุณพ่อ · อาร์'}</strong></div><span class="online-indicator" aria-label="กำลังใช้งาน"></span></div>
 <div class="settings-actions"><button class="settings-action" data-act="switch-role"><span class="settings-action__icon">${ico('refresh-cw')}</span><span>${role?'เปลี่ยนเป็นคุณพ่อ':'เปลี่ยนเป็นคุณแม่'}</span>${ico('chevron-right')}</button><button class="settings-action" data-act="lock"><span class="settings-action__icon">${ico('lock-keyhole')}</span><span>ล็อกหน้าจอ</span>${ico('chevron-right')}</button></div>
 <div class="pmp-passkey-settings"><div>${ico('fingerprint')} <strong>Passkey: เข้าได้โดยไม่ต้องใช้อีเมล</strong><p>เพิ่ม Face ID, ลายนิ้วมือ หรือ PIN เครื่องสำหรับบัญชีนี้ หลังจากเปิด Passkeys ใน Supabase Dashboard</p></div><button class="btn btn-light" type="button" data-act="passkey-register" ${state.demo?'disabled':''}>${ico('plus')} เพิ่ม Passkey</button></div><p class="settings-footnote">${ico('info')} ระบบจำโปรไฟล์ที่ปลดล็อกล่าสุดบนเครื่องนี้ PIN เป็นล็อกหน้าจอเท่านั้น ไม่ใช่การยืนยันสิทธิ์แทน Supabase Auth</p><button class="inline-danger" data-act="reset-pin">${ico('rotate-ccw')} ล้าง PIN ในอุปกรณ์นี้</button></section>
 <section class="settings-panel settings-baby"><div class="panel-heading"><span class="panel-icon peach">${ico('baby')}</span><div><span class="panel-eyebrow">03 · LITTLE ONE</span><h2>ชื่อของเจ้าตัวเล็ก</h2></div><span class="gender-chip">${ico('heart')} ${gender}</span></div>
 <div class="baby-gender-select"><div class="baby-gender-select__head"><div><strong>เลือกเพศลูกจากผลตรวจ</strong><small>อัปเดตเมื่อทราบผล NIPT หรือได้รับการยืนยันจากแพทย์</small></div>${ico('scan-heart')}</div><div class="baby-gender-options" role="group" aria-label="เพศลูกที่ได้รับการยืนยัน"><button type="button" data-baby-gender="unknown" class="${b.gender==='unknown'?'is-active':''}" aria-pressed="${b.gender==='unknown'}">${ico('help-circle')} ยังไม่ทราบ</button><button type="button" data-baby-gender="female" class="${b.gender==='female'?'is-active girl':''}" aria-pressed="${b.gender==='female'}">${ico('flower-2')} ลูกสาว</button><button type="button" data-baby-gender="male" class="${b.gender==='male'?'is-active boy':''}" aria-pressed="${b.gender==='male'}">${ico('star')} ลูกชาย</button></div></div>
 ${b.known?`<div class="baby-selected-name ${b.gender==='female'?'girl':'boy'}"><span>${ico('heart-handshake')} เราจะเรียกเจ้าตัวเล็กว่า</span><strong>${esc(b.displayTh)}</strong><div>${esc(b.english||'')} ${b.fullTh?' · '+esc(b.fullTh):''}</div><small>ชื่อบน Dashboard และสมุดความทรงจำจะเปลี่ยนตามที่เลือกโดยอัตโนมัติ</small></div>`:`<div class="baby-selected-name unknown">${ico('heart')} ตอนนี้ยังใช้คำว่า “ลูกน้อย” จนกว่าจะเลือกเพศจากผลตรวจ</div>`}
 <div class="baby-names"><div class="baby-name baby-name--girl ${b.gender==='female'?'is-selected':b.known?'is-inactive':''}"><div class="baby-name__top"><span class="baby-name__icon">${ico('flower')}</span><span>IF IT'S A GIRL</span></div><strong>${esc(s.girlNickTh||'พิวรีน')}</strong><span class="baby-name__latin">${esc(s.girlNickEn||'Purine')}</span><p>${esc(s.girlThai)}</p></div><div class="baby-name baby-name--boy ${b.gender==='male'?'is-selected':b.known?'is-inactive':''}"><div class="baby-name__top"><span class="baby-name__icon">${ico('star')}</span><span>IF IT'S A BOY</span></div><strong>${esc(s.boyNickTh||'อันเซล')}</strong><span class="baby-name__latin">${esc(s.boyNickEn||'Ansel')}</span><p>${esc(s.boyThai)}</p></div></div>
 <button class="btn btn-light baby-edit" data-act="edit-family">${ico('pencil-line')} แก้ไขชื่อและข้อมูลลูก ${ico('arrow-right')}</button></section>
 <section class="settings-panel settings-account"><div class="panel-heading"><span class="panel-icon mint">${ico('shield-check')}</span><div><span class="panel-eyebrow">04 · FAMILY SHARING</span><h2>บัญชีและความเป็นส่วนตัว</h2></div></div>
 <div class="sharing-note"><div class="sharing-note__icon">${ico('heart-handshake')}</div><div><strong>เรื่องราวของเรา แชร์กันสองคน</strong><p>เชิญสมาชิกด้วยอีเมลที่ใช้สมัคร Supabase เพื่อร่วมบันทึกและดูข้อมูลครอบครัว</p></div></div>
 <button class="btn settings-main-action account-invite" data-act="invite">${ico('user-round-plus')} เชิญสมาชิกครอบครัว ${ico('arrow-up-right')}</button><button class="settings-signout" data-act="logout">${ico('log-out')} ออกจากระบบ ${ico('arrow-right')}</button></section></div><div style="margin-top:20px">${v7Settings()}</div>`}function openAction(act){if(act==='edit-family'){const s=state.data.settings;showModal('ข้อมูลครอบครัว',field('วันกำหนดคลอด','dueDate','date',s.dueDate)+field('วันที่ทราบว่าตั้งครรภ์','discoveredAt','date',s.discoveredAt)+field('อายุคุณแม่ในวันที่ทราบ','motherAge','number',s.motherAge)+field('น้ำหนักเริ่มต้น (กก.)','initialWeight','number',s.initialWeight,'step="0.1"')+field('วิธีที่ทราบ','discoveryMethod','text',s.discoveryMethod)+`<div class="field"><label>เพศ (ตามผลตรวจ)</label><select name="gender"><option value="unknown">ยังไม่ทราบ</option><option value="female" ${s.gender==='female'?'selected':''}>หญิง</option><option value="male" ${s.gender==='male'?'selected':''}>ชาย</option></select></div>`+field('ชื่อจริงลูกสาว (ไทย)','girlThai','text',s.girlThai)+field('ชื่อจริงลูกสาว (อังกฤษ)','girlEn','text',s.girlEn)+field('ชื่อเล่นลูกสาว (ไทย)','girlNickTh','text',s.girlNickTh)+field('ชื่อเล่นลูกสาว (อังกฤษ)','girlNickEn','text',s.girlNickEn)+field('ชื่อจริงลูกชาย (ไทย)','boyThai','text',s.boyThai)+field('ชื่อจริงลูกชาย (อังกฤษ)','boyEn','text',s.boyEn)+field('ชื่อเล่นลูกชาย (ไทย)','boyNickTh','text',s.boyNickTh)+field('ชื่อเล่นลูกชาย (อังกฤษ)','boyNickEn','text',s.boyNickEn)+field('วันที่คลอดจริง (เมื่อคลอดแล้ว)','birthDate','date',s.birthDate));$('#entryForm').onsubmit=async e=>{e.preventDefault();MOD.innerHTML='';await mergeSettings(formValues(e))};return}
if(act==='symptom'){showModal('บันทึกอาการคุณแม่',field('วันที่','date','date',today())+`<div class="field"><label>ระดับอารมณ์ (1–5)</label><select name="mood"><option value="3">3 · ปกติ</option><option value="1">1 · ไม่สบายใจมาก</option><option value="2">2 · ไม่ค่อยดี</option><option value="4">4 · ดี</option><option value="5">5 · ดีมาก</option></select></div>`+area('อาการและข้อสังเกต','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);MOD.innerHTML='';await addItem('symptoms',v)};return}
if(act==='appointment'){showModal('นัดหมายแพทย์',field('วันและเวลา','at','datetime-local','', 'required')+field('หัวข้อการนัด','title','text','', 'required')+field('สถานที่','place')+field('แพทย์ผู้ตรวจ','doctor')+area('สิ่งที่จะตรวจ / เตรียมตัว','purpose'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);v.at=new Date(v.at).toISOString();MOD.innerHTML='';await addItem('appointments',v)};return}
if(act==='task'){showModal('เพิ่มรายการเตรียมของ',field('สิ่งที่ต้องเตรียม','title','text','','required')+`<div class="field"><label>หมวด</label><select name="category">${Object.entries(catLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div>`+field('จำนวน','quantity','number','1','min="1" step="1"')+field('งบประมาณ (บาท)','budget','number','','min="0" step="0.01"')+field('ราคาซื้อจริง (บาท)','spent','number','','min="0" step="0.01"')+field('ร้านค้า/หมายเหตุ','shop'));$('#entryForm').onsubmit=async e=>{e.preventDefault();MOD.innerHTML='';await addItem('tasks',{...formValues(e),done:false})};return}
if(act==='photo'){showModal('เก็บภาพความทรงจำ',`<div class="field"><label>เลือกภาพ (JPG, PNG, WEBP)</label><input type="file" name="file" accept="image/jpeg,image/png,image/webp" required></div><div class="field"><label>อัลบั้ม</label><select name="category">${Object.entries(photoTypes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div>`+`<div id="bumpInputs" class="v7-bump-form">${field('เดือนที่ถ่าย (สำหรับภาพคุณแม่)','month','number','','min="1" max="9" step="1"')}${field('อายุครรภ์ขณะถ่าย (สัปดาห์ ถ้าทราบ)','week','number','','min="0" max="45" step="0.1"')}</div>`+field('คำบรรยาย','caption')+area('ข้อความให้ลูกอ่านในอนาคต','note')+field('วันที่ถ่าย','takenAt','date',today()));const cat=$('#entryForm [name=category]');function toggle(){const wrap=$('#bumpInputs');if(wrap)wrap.style.display=cat.value==='bump'?'block':'none'}cat.addEventListener('change',toggle);toggle();$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e),file=e.currentTarget.querySelector('[name=file]').files[0];if(v.category==='bump'&&v.month&&(Number(v.month)<1||Number(v.month)>9))return toast('เดือนของภาพคุณแม่ต้องอยู่ระหว่าง 1–9',true);MOD.innerHTML='';try{await uploadPhoto(file,v.category,v.caption,v.takenAt,{month:v.category==='bump'?v.month:'',week:v.category==='bump'?v.week:'',note:v.note})}catch(err){toast(err.message,true)}};return}
if(act==='kick'){showModal('นับลูกดิ้น',`<p class="notice warn">การนับลูกดิ้นเป็นการติดตามส่วนบุคคล หากลูกดิ้นน้อยลง หยุดดิ้น หรือมีการเปลี่ยนแปลงจากรูปแบบปกติ ให้ติดต่อหน่วยฝากครรภ์หรือห้องคลอดทันที อย่ารอดูตัวเลขในแอป</p><div class="kick-counter"><b id="kickNumber">0</b><span>ครั้ง</span><button type="button" class="btn" id="kickTap">${ico('heart')} ดิ้นหนึ่งครั้ง</button></div><p class="micro">กดเมื่อรู้สึกถึงการเคลื่อนไหวจริง ระบบไม่ตัดสินความปลอดภัยจากจำนวนครั้ง</p>`,'จบและบันทึก');const started=Date.now();let count=0;$('#kickTap').onclick=()=>{$('#kickNumber').textContent=String(++count)};$('#entryForm').onsubmit=async e=>{e.preventDefault();MOD.innerHTML='';await addItem('kicks',{count,minutes:Math.max(1,Math.round((Date.now()-started)/60000))})};iconize();return}
if(act==='baby-log'){showModal(`บันทึก${babyIdentity().displayTh}หลังคลอด`,field('วันที่','date','date',today())+`<div class="field"><label>ประเภท</label><select name="type"><option>การให้นม</option><option>การนอน</option><option>เปลี่ยนผ้าอ้อม</option><option>หมายเหตุ</option></select></div>`+area('รายละเอียด','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();MOD.innerHTML='';await addItem('babyLogs',formValues(e))};return}
if(act==='growth'){showModal(`การเติบโตของ${babyIdentity().displayTh}`,field('วันที่','date','date',today())+field('น้ำหนัก (กก.)','weight','number','','step="0.01"')+field('ความยาว (ซม.)','length','number','','step="0.1"'));$('#entryForm').onsubmit=async e=>{e.preventDefault();MOD.innerHTML='';await addItem('growth',formValues(e))};return}
if(act==='invite'){showModal('เชิญสมาชิกครอบครัว',field('อีเมลของอีกฝ่าย','email','email','','required'));$('#entryForm').onsubmit=async e=>{e.preventDefault();if(state.demo)return toast('ต้องเชื่อม Supabase ก่อน',true);const {error}=await db.rpc('invite_parent',{p_family:state.family.id,p_email:formValues(e).email});if(error)return toast(error.message,true);MOD.innerHTML='';toast('บันทึกคำเชิญแล้ว ให้อีกฝ่ายสมัครและล็อกอินด้วยอีเมลนี้')};return}}
/* v7 Journey extension: descriptive tracking, no health-risk classifier. */
const v7num=x=>{if(x===null||x===undefined||String(x).trim()==='')return null;const n=Number(x);return Number.isFinite(n)?n:null};
const v7money=x=>{const n=v7num(x);return n===null?'—':new Intl.NumberFormat('th-TH',{maximumFractionDigits:0}).format(n)+' ฿'};
const v7date=x=>x?fmtDate(String(x).slice(0,10)):'—';
const v7btn=(act,icon,label)=>`<button class="btn btn-light" data-act="${act}">${ico(icon)} ${esc(label)}</button>`;
const v7row=(title,subtitle,meta='',icon='heart',extra='')=>`<div class="v7-record"><span class="v7-record__icon">${ico(icon)}</span><div class="v7-record__body"><strong>${esc(title)}</strong><small>${esc(subtitle)}</small></div><span class="v7-record__meta">${esc(meta)}</span>${extra}</div>`;
const v7header=(kicker,title,description,icon='book-heart')=>`<div class="v7-section-banner"><span class="v7-banner-icon">${ico(icon)}</span><div><span class="v7-kicker">${esc(kicker)}</span><h2>${esc(title)}</h2><p>${esc(description)}</p></div></div>`;
function v7Timeline(){const p=pregnancy(),born=isBorn(),s=state.data.settings,month=p?Math.min(9,Math.max(1,Math.ceil(p.days/30.44))):null;let target=born?`${babyIdentity().displayTh}มาอยู่กับเราแล้ว`:p?`สัปดาห์ที่ ${p.weeks} + ${p.remainder} วัน`:'ยังไม่ระบุกำหนดคลอด';return `<section class="v7-timeline"><div class="v7-timeline__top"><span>${ico('sparkles')} OUR JOURNEY</span><span>${born?'BABY CHAPTER':'PREGNANCY CHAPTER'}</span></div><h2>${target}</h2><p>${born?`ครบ ${daysBaby()} วันหลังคลอด — บันทึกช่วงเวลาแรก ๆ ของ${babyIdentity().displayTh}`:p?`เดือนประมาณที่ ${month} จากกำหนดคลอดที่คุณบันทึกไว้`:'ระบุวันกำหนดคลอดจากทีมฝากครรภ์ในหน้าตั้งค่าเพื่อเปิดไทม์ไลน์'}</p><div class="v7-timeline__steps">${Array.from({length:9},(_,i)=>`<div class="v7-timeline__step ${p&&month>=i+1?'active':''} ${p&&month===i+1?'current':''}"><span>${i+1}</span><small>M${i+1}</small></div>`).join('')}</div><div class="v7-timeline__actions"><button class="btn btn-light" data-tab="photos" data-gallery="bump">${ico('camera')} 9 Months of Mommy</button><button class="btn btn-light" data-tab="journey" data-care="pink">${ico('book-heart')} สมุดสีชมพู</button></div><small class="v7-muted">เดือนเป็นการประมาณจากอายุครรภ์ ไม่ใช่ผลตรวจพัฒนาการ</small></section>`}
function v7Upcoming(){const appts=upcoming().map(a=>({at:a.at,label:a.title||'นัดแพทย์',info:`${a.place||''} ${a.doctor||''}`,tag:'doctor',id:a.id}));const reminders=arr('reminders').filter(x=>x.done!==true&&x.when).map(x=>({at:x.when,label:x.title,info:x.note||'',tag:'reminder',id:x.id}));const vacc=arr('vaccines').filter(x=>x.dueDate&&!x.givenDate).map(x=>({at:x.dueDate,label:'นัดวัคซีน: '+(x.title||''),info:x.place||'',tag:'vaccine'}));return [...appts,...reminders,...vacc].filter(x=>!Number.isNaN(new Date(x.at).valueOf())&&new Date(x.at)>=new Date(Date.now()-86400000)).sort((a,b)=>new Date(a.at)-new Date(b.at)).slice(0,4)}
function v7Home(){const items=v7Upcoming(),acts=[['pink','book-heart','สมุดสีชมพู'],['analytics','chart-line','กราฟสุขภาพ'],['vaccines','syringe','วัคซีนลูก'],['newborn','baby','หลังคลอด']];const activity=[...['appointments','symptoms','prenatalVisits','memories','photos','babyLogs','growth','vaccines','tasks','postpartumLogs','reminders'].flatMap(k=>arr(k).map(x=>({...x,_k:k})))].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,4);return `${v7Timeline()}<div class="v7-header-row"><div><span class="v7-kicker">HEALTH & FAMILY</span><h2>จัดการทุกเรื่องสำคัญ</h2></div></div><div class="v7-shortcuts">${acts.map(([id,icon,t])=>`<button data-tab="journey" data-care="${id}">${ico(icon)}<span>${esc(t)}</span>${ico('arrow-up-right')}</button>`).join('')}</div><div class="v7-grid"><section class="v7-surface"><div class="v7-header-row"><h3>${ico('bell')} เตือนความจำ</h3>${v7btn('reminder','plus','เพิ่ม')}</div>${items.length?items.map(x=>v7row(x.label,x.info||'โปรดตรวจรายละเอียดใบนัด',v7date(x.at),x.tag==='vaccine'?'syringe':x.tag==='doctor'?'stethoscope':'bell',x.tag==='reminder'?`<button class="v7-ics" type="button" data-reminder-ics="${esc(x.id)}" title="ส่งไปปฏิทิน">${ico('calendar-plus')}</button>`:'')).join(''):empty('ไม่มีรายการใกล้ถึง','calendar-check')}<p class="v7-muted">แสดงในแอปเมื่อเปิดใช้งาน; การแจ้งเตือนพื้นหลังต้องเชื่อมบริการส่ง Push เพิ่มเติม</p></section><section class="v7-surface"><div class="v7-header-row"><h3>${ico('heart-handshake')} กิจกรรมครอบครัว</h3>${v7btn('memory','plus','บันทึก')}</div>${activity.length?activity.map(x=>v7row(x.title||x.caption||x.note||x.type||'เพิ่มบันทึก',({'appointments':'นัดหมาย','symptoms':'อาการ','prenatalVisits':'ผลตรวจครรภ์','memories':'ข้อความถึงลูก','photos':'ภาพครอบครัว','babyLogs':'ดูแลลูก','growth':'การเติบโต','vaccines':'วัคซีน','tasks':'เตรียมของ','postpartumLogs':'หลังคลอด','reminders':'แจ้งเตือน'})[x._k]||'บันทึก',v7date(x.createdAt),'heart')).join(''):empty('ยังไม่มีความเคลื่อนไหวในครอบครัว','book-heart')}</section></div>`}
function v7Pink(){const entries=ordered('prenatalVisits').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));return `${v7header('DIGITAL MATERNAL RECORD','สมุดสีชมพูดิจิทัล','บันทึกผลตรวจตามใบนัดและผลที่แพทย์แจ้ง ไม่ใช้แทนสมุดประจำตัวจริง','book-heart')}<div class="v7-toolbar">${v7btn('prenatal','plus','เพิ่มผลตรวจฝากครรภ์')}${v7btn('print-book','printer','พิมพ์ / บันทึก PDF')}</div><div class="v7-tiles"><div><span>ANC VISITS</span><b>${entries.length}</b><small>ครั้งที่บันทึก</small></div><div><span>NEXT APPOINTMENTS</span><b>${upcoming().length}</b><small>นัดหมายที่กำลังมาถึง</small></div></div>${entries.length?entries.map(x=>`<div class="v7-visit"><div class="v7-visit__date">${ico('calendar-heart')} ${esc(fmtDate(x.date))}</div><h3>${esc(x.title||'ฝากครรภ์')}</h3><div class="v7-info-grid"><span>น้ำหนักแม่ <strong>${esc(x.weight||'—')} กก.</strong></span><span>ความดัน <strong>${esc(x.sys||'—')}/${esc(x.dia||'—')} mmHg</strong></span><span>อายุครรภ์ <strong>${esc(x.gestWeek||'—')} สัปดาห์</strong></span><span>แพทย์ <strong>${esc(x.doctor||'—')}</strong></span></div>${x.note?`<p>${esc(x.note)}</p>`:''}</div>`).join(''):empty('เพิ่มผลตรวจครั้งแรกตามข้อมูลที่ได้รับจากสถานพยาบาล','clipboard-plus')}<p class="notice">ค่าต่าง ๆ เป็นข้อมูลที่ผู้ใช้กรอก ไม่ได้ผ่านการตรวจสอบทางการแพทย์</p>`}
function v7Analytics(){const pn=[...arr('prenatalVisits')].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));const mood=[...arr('symptoms')].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));const baby=[...arr('growth')].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));function trend(list,key,label,unit){const data=list.filter(x=>v7num(x[key])!==null);const first=data[0],last=data.at(-1);const delta=data.length>1?v7num(last[key])-v7num(first[key]):null;return `<section class="v7-analytic"><div class="v7-analytic__head"><h3>${esc(label)}</h3><span>${data.length} รายการ</span></div><strong>${last?esc(last[key])+' '+esc(unit):'—'}</strong><small>${delta===null?'ต้องมีอย่างน้อย 2 รายการเพื่อดูการเปลี่ยนแปลง':`เปลี่ยน ${delta>0?'+':''}${Number(delta.toFixed(2))} ${esc(unit)} จากครั้งแรกที่บันทึก`}</small>${chart(data.map(x=>({value:x[key]})))}<p>แสดงค่าจากบันทึกจริง ไม่ใช่เกณฑ์ทางคลินิก</p></section>`}return `${v7header('PERSONAL TRENDS','Health Insights','สถิติเชิงพรรณนาและกราฟจากบันทึกของครอบครัว ไม่คำนวณความเสี่ยงหรือวินิจฉัยโรค','chart-line')}<div class="v7-analytics">${trend(pn,'weight','น้ำหนักคุณแม่ (ANC)','กก.')}${trend(pn,'sys','ความดันตัวบน','mmHg')}${trend(pn,'dia','ความดันตัวล่าง','mmHg')}${trend(mood,'mood','อารมณ์ที่บันทึก','คะแนน')}${trend(baby,'weight','น้ำหนักลูกหลังคลอด','กก.')}${trend(baby,'length','ความยาวลูกหลังคลอด','ซม.')}</div><div class="notice warn">หากมีอาการผิดปกติหรือกังวลเกี่ยวกับสุขภาพ ให้ปรึกษาผู้ดูแลรักษาโดยไม่รอผลกราฟจากแอป</div>`}
function v7Newborn(){const born=isBorn();return `${v7header('BABY & POSTPARTUM','บันทึกหลังคลอด','ติดตามนม การนอน ผ้าอ้อม น้ำหนัก พัฒนาการและสุขภาพคุณแม่','baby')}<div class="v7-babyhead"><div><span>${born?'BABY IS HOME':'READY FOR BABY CHAPTER'}</span><h2>${born?`${esc(babyIdentity().displayTh)}อายุ ${daysBaby()} วัน`:'ยังไม่ได้บันทึกวันคลอดจริง'}</h2><p>${born?`คลอดวันที่ ${fmtDate(state.data.settings.birthDate)}`:'เมื่อบันทึกวันคลอดในหน้าตั้งค่า จะเริ่มติดตามอายุหลังคลอดโดยอัตโนมัติ'}</p></div>${ico('baby')}</div><div class="v7-toolbar">${v7btn('baby-log','milk','นม / นอน / ผ้าอ้อม')}${v7btn('growth','ruler','น้ำหนัก–ส่วนยาว')}${v7btn('postpartum','heart-pulse','สุขภาพคุณแม่')}${v7btn('milestone','star','พัฒนาการ')}</div><div class="v7-grid"><section class="v7-surface"><h3>สมุดประจำวันของ${esc(babyIdentity().displayTh)}</h3>${ordered('babyLogs').slice(0,10).map(x=>v7row(x.type||'บันทึกลูก',x.note||'',v7date(x.date),'milk')).join('')||empty('ยังไม่บันทึกการดูแลลูก')}</section><section class="v7-surface"><h3>ติดตามคุณแม่หลังคลอด</h3>${ordered('postpartumLogs').slice(0,10).map(x=>v7row(x.title||'ติดตามหลังคลอด',x.note||'',v7date(x.date),'heart-pulse')).join('')||empty('ยังไม่มีบันทึกหลังคลอด')}</section></div><div class="v7-surface" style="margin-top:15px"><h3>พัฒนาการและช่วงเวลาสำคัญ</h3>${ordered('memories').filter(x=>x.kind==='milestone').map(x=>v7row(x.title,x.note||'',v7date(x.date),'star')).join('')||empty('ยังไม่เพิ่มพัฒนาการ')}</div>`}
function v7Vaccines(){const vacc=ordered('vaccines');return `${v7header('VACCINE JOURNAL','วัคซีนและนัดติดตาม','บันทึกชื่อวัคซีน วันรับจริง สถานที่ และใบนัดที่ได้รับจากโรงพยาบาล','syringe')}<div class="v7-toolbar">${v7btn('vaccine','plus','เพิ่มวัคซีน')}${v7btn('print-book','printer','พิมพ์บันทึก')}</div><div class="notice">ตารางนี้ไม่สร้างกำหนดวัคซีนเอง โปรดใช้วันนัดตามสมุดสุขภาพเด็กและคำแนะนำสถานพยาบาล</div>${vacc.length?vacc.map(x=>`<div class="v7-visit"><div class="v7-visit__date">${ico('syringe')} ${esc(x.title||'รายการวัคซีน')}</div><div class="v7-info-grid"><span>ได้รับจริง <strong>${esc(v7date(x.givenDate))}</strong></span><span>กำหนดนัด <strong>${esc(v7date(x.dueDate))}</strong></span><span>สถานที่ <strong>${esc(x.place||'—')}</strong></span><span>เลขเข็ม <strong>${esc(x.dose||'—')}</strong></span></div>${x.note?`<p>${esc(x.note)}</p>`:''}</div>`).join(''):empty('ยังไม่มีรายการวัคซีน','syringe')}`}
function v7CareTabs(){const items=[['overview','heart-pulse','ประจำวัน'],['pink','book-heart','สมุดสีชมพู'],['analytics','chart-line','กราฟ'],['newborn','baby','หลังคลอด'],['vaccines','syringe','วัคซีน']];return `<div class="v7-tabs" role="tablist" aria-label="สมุดสุขภาพ">${items.map(([key,sym,label])=>`<button type="button" role="tab" aria-selected="${state.careTab===key}" class="${state.careTab===key?'active':''}" data-care="${key}">${ico(sym)} ${label}</button>`).join('')}</div>`}
function v7Memories(){const items=ordered('memories').filter(x=>x.kind!=='milestone');return `<section class="v7-surface v7-memory"><div class="v7-header-row"><div><span class="v7-kicker">DEAR LITTLE ONE</span><h2>จดหมายและความทรงจำถึง${esc(babyIdentity().displayTh)}</h2></div>${v7btn('memory','pen-line','เขียนถึงลูก')}</div>${items.length?items.map(x=>`<div class="v7-letter"><span>${ico('heart')} ${v7date(x.date||x.createdAt)}</span><strong>${esc(x.title||'ถึง'+babyIdentity().displayTh)}</strong><p>${esc(x.note||'')}</p></div>`).join(''):'<p class="muted">ข้อความแรกถึงลูกอาจเป็นเรื่องเล็ก ๆ ที่มีความหมายในวันที่ลูกโตขึ้น</p>'}</section>`}
function v7Bump(){const entries=arr('photos').filter(x=>x.category==='bump').sort((a,b)=>(Number(a.month||0)-Number(b.month||0))||String(a.takenAt||'').localeCompare(String(b.takenAt||'')));return `<section class="v7-surface v7-bump"><div class="v7-header-row"><div><span class="v7-kicker">9 MONTHS OF MOMMY</span><h2>ภาพคุณแม่กับ${esc(babyIdentity().displayTh)}ในท้อง ♡</h2></div>${v7btn('bump-photo','camera','เพิ่มภาพ')}</div><p class="muted">ถ่ายเมื่อไร เดือนที่เท่าไร เล่าเรื่องอะไรให้ลูกฟัง — เก็บไว้เปิดดูด้วยกันในอนาคต</p><div class="v7-bump-grid">${Array.from({length:9},(_,i)=>{const month=i+1,pic=entries.filter(x=>Number(x.month)===month).at(-1);return `<button type="button" class="v7-month-tile ${pic?'has-photo':''}" ${pic?`data-view-photo="${esc(pic.id)}"`:'data-act="bump-photo"'} title="เพิ่มภาพเดือนที่ ${month}"><span>MONTH ${month.toString().padStart(2,'0')}</span>${pic&&state.mediaUrls[pic.id]?`<img loading="lazy" src="${esc(state.mediaUrls[pic.id])}" alt="${esc(pic.caption||`ภาพคุณแม่เดือนที่ ${month}`)}">`:`<span class="v7-month-empty">${ico('heart')}<small>บันทึกภาพเดือนที่ ${month}</small></span>`}${pic?`<small>${esc(pic.caption||'ความทรงจำเดือนนี้')} · ${esc(v7date(pic.takenAt))}</small>`:''}</button>`}).join('')}</div>${entries.filter(x=>!Number(x.month)).length?`<h3>ภาพที่ไม่ได้ระบุเดือน</h3>${entries.filter(x=>!Number(x.month)).map(x=>v7row(x.caption||'ภาพคุณแม่','ไม่ได้ระบุเดือน',v7date(x.takenAt),'camera')).join('')}`:''}</section>`}
function v7Budget(){const items=arr('tasks'),sum=k=>items.reduce((n,t)=>n+(v7num(t[k])||0),0),budget=sum('budget'),spent=sum('spent');return `<div class="v7-budget"><div><span>ESTIMATED BUDGET</span><strong>${v7money(budget)}</strong></div><div><span>ACTUAL SPENT</span><strong>${v7money(spent)}</strong></div><div><span>REMAINING / DIFFERENCE</span><strong>${v7money(budget-spent)}</strong></div></div>`}
function v7ShoppingList(){return `<section class="v7-surface"><div class="v7-header-row"><div><span class="v7-kicker">BABY SHOPPING PLANNER</span><h2>วางแผนซื้อของและค่าใช้จ่าย</h2></div>${v7btn('task','plus','เพิ่มรายการ')}</div>${v7Budget()}<p class="v7-muted">แตะ “แก้ไขงบ” ของแต่ละรายการ เพื่อกรอกราคาเป้าหมาย จำนวน ราคาจริง และบันทึกร้านค้า ตัวเลขเป็นงบส่วนตัว ไม่ใช่คำแนะนำทางการแพทย์</p></section>`}
function v7Settings(){return `<div class="v7-surface v7-privacy"><div class="v7-header-row"><div><span class="v7-kicker">DATA & SECURITY</span><h2>ข้อมูลครอบครัวและการสำรอง</h2></div>${ico('shield-check')}</div><p>PIN เข้าแอปได้โดยไม่กรอกอีเมลซ้ำ ขณะที่เซสชัน Supabase ยังใช้งานได้บนอุปกรณ์นี้</p><div class="v7-toolbar">${v7btn('export-json','download','สำรองข้อมูล JSON')}${v7btn('print-book','printer','พิมพ์สมุดสุขภาพ')}${v7btn('lock','lock-keyhole','ล็อกตอนนี้')}</div><div class="notice">ไฟล์ส่งออกอาจมีข้อมูลสุขภาพและชื่อสมาชิกครอบครัว โปรดเก็บไว้ในพื้นที่ส่วนตัว หลีกเลี่ยงการแชร์โดยไม่ตั้งใจ การดาวน์โหลด JSON ไม่รวมไฟล์ภาพต้นฉบับ</div></div>`}
function v7Download(content,filename,mime){const blob=new Blob([content],{type:mime}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),15000)}
function v7Export(){if(!confirm('ข้อมูลสำรองมีชื่อและข้อมูลสุขภาพของครอบครัว ต้องการดาวน์โหลดไฟล์ JSON ลงอุปกรณ์หรือไม่?'))return;v7Download(JSON.stringify({...state.data,exportedAt:new Date().toISOString(),format:'PMP v7 JSON export, photos metadata only'},null,2),'pregnant-manager-pro-backup-'+today()+'.json','application/json;charset=utf-8');toast('ส่งออก JSON แล้ว (ไม่รวมรูปต้นฉบับ)')}
function v7Print(){const s=state.data.settings,rows=(items,fn)=>items.map(fn).join(''),root=document.getElementById('pmpPrintRoot')||(()=>{const d=document.createElement('div');d.id='pmpPrintRoot';document.body.appendChild(d);return d})();root.innerHTML=`<div class="v7-print"><h1>Pregnant Manager Pro — Family Health Journal</h1><p>คุณแม่: ${esc(s.mother)} · คุณพ่อ: ${esc(s.father)}</p><p>ชื่อที่ใช้เรียกลูก: ${esc(babyIdentity().displayTh)} ${esc(babyIdentity().english)} · เพศที่บันทึก: ${esc(babyIdentity().sexLabel)}</p><p>กำหนดคลอดโดยประมาณ: ${esc(v7date(s.dueDate))} · วันคลอดจริง: ${esc(v7date(s.birthDate))}</p><h2>ผลตรวจฝากครรภ์</h2><table><thead><tr><th>วันที่</th><th>น้ำหนัก</th><th>ความดัน</th><th>หมายเหตุ</th></tr></thead><tbody>${rows(ordered('prenatalVisits'),x=>`<tr><td>${esc(v7date(x.date))}</td><td>${esc(x.weight||'')}</td><td>${esc(x.sys||'')}/${esc(x.dia||'')}</td><td>${esc(x.note||'')}</td></tr>`)}</tbody></table><h2>การเติบโตของลูก</h2><table><thead><tr><th>วันที่</th><th>น้ำหนัก</th><th>ความยาว</th></tr></thead><tbody>${rows(ordered('growth'),x=>`<tr><td>${esc(v7date(x.date))}</td><td>${esc(x.weight||'')}</td><td>${esc(x.length||'')}</td></tr>`)}</tbody></table><h2>วัคซีน</h2><table><thead><tr><th>ชื่อ</th><th>วันที่ได้รับ</th><th>วันนัด</th></tr></thead><tbody>${rows(ordered('vaccines'),x=>`<tr><td>${esc(x.title||'')}</td><td>${esc(v7date(x.givenDate))}</td><td>${esc(v7date(x.dueDate))}</td></tr>`)}</tbody></table><p>เอกสารสรุปจากข้อมูลที่ผู้ใช้กรอกเอง ไม่ใช่เอกสารรับรองทางการแพทย์</p></div>`;window.print()}
function v7Ics(x){if(!x?.when)return;const d=new Date(x.when),end=new Date(d.getTime()+3600000),fmt=t=>t.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const safe=t=>String(t||'').replace(/\\/g,'\\\\').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n');v7Download(`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Pregnant Manager Pro//EN\r\nBEGIN:VEVENT\r\nUID:${oid()}@pregnant-manager-pro\r\nDTSTAMP:${fmt(new Date())}\r\nDTSTART:${fmt(d)}\r\nDTEND:${fmt(end)}\r\nSUMMARY:${safe(x.title||'Family reminder')}\r\nDESCRIPTION:${safe(x.note||'')}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`, 'family-reminder.ics','text/calendar;charset=utf-8')}
function v7Form(act){if(act==='prenatal'){showModal('เพิ่มผลตรวจฝากครรภ์',field('วันที่ตรวจ','date','date',today(),'required')+field('หัวข้อการตรวจ','title','text','ฝากครรภ์')+field('อายุครรภ์ตามแพทย์ (สัปดาห์)','gestWeek','number','','min="0" max="45" step="0.1"')+field('น้ำหนักคุณแม่ (กก.)','weight','number','','step="0.1" min="0" max="350"')+field('ความดันตัวบน (mmHg)','sys','number','','step="1" min="0" max="300"')+field('ความดันตัวล่าง (mmHg)','dia','number','','step="1" min="0" max="200"')+field('ชื่อแพทย์','doctor')+field('สถานพยาบาล','place')+area('ผลตรวจ/หมายเหตุจากแพทย์','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);MOD.innerHTML='';await addItem('prenatalVisits',v)};return true}
if(act==='vaccine'){showModal(`บันทึกวัคซีน${babyIdentity().displayTh}`,field('ชื่อวัคซีน','title','text','','required')+field('เข็ม/ครั้งที่','dose')+field('วันที่ได้รับจริง','givenDate','date')+field('วันที่แพทย์นัด (ถ้ามี)','dueDate','date')+field('สถานพยาบาล','place')+area('หมายเหตุ','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);MOD.innerHTML='';await addItem('vaccines',v)};return true}
if(act==='postpartum'){showModal('บันทึกสุขภาพคุณแม่หลังคลอด',field('วันที่','date','date',today(),'required')+field('หัวข้อ','title','text','ติดตามสุขภาพหลังคลอด')+area('อาการ/ข้อสงสัยเพื่อแจ้งแพทย์','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);MOD.innerHTML='';await addItem('postpartumLogs',v)};return true}
if(act==='memory'||act==='milestone'){showModal(act==='milestone'?'บันทึกพัฒนาการลูก':`เขียนข้อความถึง${babyIdentity().displayTh}`,field('วันที่','date','date',today(),'required')+field('ชื่อเรื่อง','title','text',act==='milestone'?'ช่วงเวลาสำคัญ':`ถึง${babyIdentity().displayTh}`,'required')+area('บันทึกความทรงจำ','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v={...formValues(e),kind:act==='milestone'?'milestone':'letter'};MOD.innerHTML='';await addItem('memories',v)};return true}
if(act==='reminder'){showModal('เพิ่มการแจ้งเตือนครอบครัว',field('เตือนเรื่อง','title','text','','required')+field('วันที่และเวลา','when','datetime-local','','required')+area('รายละเอียด/ของที่ต้องเตรียม','note'));$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=formValues(e);v.when=new Date(v.when).toISOString();MOD.innerHTML='';const ok=await addItem('reminders',v);if(ok)toast('บันทึกแล้ว สามารถส่งลงปฏิทินผ่านไฟล์ .ics ได้')};return true}
if(act==='bump-photo'){openAction('photo');const select=document.querySelector('#entryForm [name=category]');if(select){select.value='bump';select.dispatchEvent(new Event('change',{bubbles:true}))}return true}
if(act==='export-json'){v7Export();return true}if(act==='print-book'){v7Print();return true}return false}

function calendarURL(a){const start=new Date(a.at),end=new Date(start.getTime()+3600000),stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(a.title||'นัดแพทย์')}&dates=${stamp(start)}/${stamp(end)}&details=${encodeURIComponent(a.purpose||'')}&location=${encodeURIComponent(a.place||'')}`}
document.addEventListener('click',async e=>{const close=e.target.closest('[data-close]');if(close){if(e.target===close||close.tagName==='BUTTON')MOD.innerHTML='';return}const digit=e.target.closest('[data-pin-digit]');if(digit){const inp=$('#pmpPinInput');if(inp){const k=digit.dataset.pinDigit;inp.value=k==='back'?inp.value.slice(0,-1):k==='clear'?'':(inp.value+k).slice(0,6);updatePinDots();}return}const pick=e.target.closest('[data-pick-role]');if(pick){state.role=pick.dataset.pickRole;renderPin();return}const ics=e.target.closest('[data-reminder-ics]');if(ics){const item=arr('reminders').find(x=>x.id===ics.dataset.reminderIcs);if(item)v7Ics(item);return}const genderPick=e.target.closest('[data-baby-gender]');if(genderPick){const value=genderPick.dataset.babyGender; if(!['unknown','female','male'].includes(value))return;if(value===babyIdentity().gender)return;const description=value==='female'?`ลูกสาว — ${state.data.settings.girlNickTh||'ยังไม่ได้ตั้งชื่อเล่น'}`:value==='male'?`ลูกชาย — ${state.data.settings.boyNickTh||'ยังไม่ได้ตั้งชื่อเล่น'}`:'ยังไม่ทราบเพศ (ใช้คำว่า ลูกน้อย)';if(!confirm(`เปลี่ยนการเรียกชื่อลูกเป็น ${description} ใช่หรือไม่?\nระบบจะเปลี่ยนการแสดงผลในทุกหน้าที่เกี่ยวข้อง โดยไม่ลบบันทึกเก่า`))return;const ok=await mergeSettings({gender:value});if(ok)toast('บันทึกเพศและอัปเดตชื่อเรียกลูกแล้ว');return}const preview=e.target.closest('[data-view-photo]');if(preview){const pic=arr('photos').find(x=>x.id===preview.dataset.viewPhoto),u=pic&&state.mediaUrls[pic.id];if(pic&&u){showModal('ภาพความทรงจำ',`<img src="${esc(u)}" style="width:100%;max-height:60vh;object-fit:contain;border-radius:15px" alt="${esc(pic.caption||'ภาพครอบครัว')}"><p class="muted" style="margin:12px 0">${esc(pic.caption||'ความทรงจำของเรา')} · ${esc(v7date(pic.takenAt))}</p><p>${esc(pic.note||'')}</p>`,'ปิด');$('#entryForm').onsubmit=ev=>{ev.preventDefault();MOD.innerHTML=''}}return}const edit=e.target.closest('[data-task-edit]');if(edit){const item=arr('tasks').find(x=>x.id===edit.dataset.taskEdit);if(item){showModal('ปรับงบ / รายการซื้อ',field('รายการ','title','text',item.title,'required')+field('จำนวน','quantity','number',item.quantity||'1','min="1" step="1"')+field('งบประมาณ (บาท)','budget','number',item.budget||'','min="0" step="0.01"')+field('ราคาซื้อจริง (บาท)','spent','number',item.spent||'','min="0" step="0.01"')+field('ร้านค้า/หมายเหตุ','shop','text',item.shop||''));$('#entryForm').onsubmit=async ev=>{ev.preventDefault();const data=formValues(ev);MOD.innerHTML='';await patchItem('tasks',item.id,data)}}return}const care=e.target.closest('[data-care]');if(care)state.careTab=care.dataset.care;const gal=e.target.closest('[data-gallery]');if(gal)state.galleryTab=gal.dataset.gallery;if((care||gal)&&!e.target.closest('[data-tab]')){render();return}const nav=e.target.closest('[data-tab]');if(nav){state.tab=nav.dataset.tab;render();return}const act=e.target.closest('[data-act]');if(!act)return;const a=act.dataset.act;if(a==='passkey-signin'){await passkeySignIn();return}if(a==='passkey-register'){await passkeyRegister();return}if(a==='demo'){demoStart();return}if(a==='logout'){logout();return}if(a==='recover-pin'){if(confirm('การตั้ง PIN ใหม่ต้องยืนยันบัญชีอีกครั้งด้วย Passkey หรืออีเมล ต้องการออกจากเซสชันเพื่อยืนยันใหม่หรือไม่?')){if(!state.demo)sessionStorage.setItem('pmp-reset-pending',JSON.stringify({uid:state.user.id,role:state.role}));logout()}return}if(a==='create-family'){await createFamily();return}if(a==='reload-family'){await loadFamily();return}if(a==='lock'){state.unlocked=null;renderPin();return}if(a==='switch-role'){const next=state.role==='mother'?'father':'mother';if(!confirm(`ต้องการเปลี่ยนเป็นโหมด${next==='mother'?'คุณแม่เอมมี่':'คุณพ่ออาร์'}หรือไม่? ระบบจะล็อกหน้าจอและให้กรอก PIN ของโปรไฟล์นั้น`))return;state.unlocked=null;state.role=next;renderPinForSwitch(next);return}if(a==='reset-pin'){if(confirm('เปลี่ยน PIN ของโปรไฟล์ปัจจุบัน? ต้องยืนยันบัญชีอีกครั้งเพื่อป้องกันผู้อื่นล้างรหัส')){if(!state.demo)sessionStorage.setItem('pmp-reset-pending',JSON.stringify({uid:state.user.id,role:state.role}));logout()}return}if(v7Form(a))return;openAction(a)});
document.addEventListener('change',async e=>{if(e.target.matches('[data-task-id]'))await patchItem('tasks',e.target.dataset.taskId,{done:e.target.checked})});
document.addEventListener('click',e=>{const t=e.target.closest('[data-auth-tab]');if(!t)return;document.querySelector('[name=authMode]').value=t.dataset.authTab;document.querySelector('#authForm button[type=submit]').textContent=t.dataset.authTab==='register'?'สมัครบัญชี':'เข้าสู่ระบบ';document.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===t))});
document.addEventListener('pointerdown',()=>{if(state.unlocked)state.lastActivity=Date.now()},{passive:true});
document.addEventListener('keydown',()=>{if(state.unlocked)state.lastActivity=Date.now()});
let hiddenSince=0;
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenSince=Date.now()}else if(hiddenSince&&Date.now()-hiddenSince>5*60*1000&&state.unlocked){state.unlocked=null;MOD.innerHTML='';renderPin()}});
setInterval(()=>{if(state.unlocked&&Date.now()-state.lastActivity>20*60*1000){state.unlocked=null;MOD.innerHTML='';renderPin()}},60000);
boot();
})();
